 void volumePanel(){android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);LinearLayout box=new LinearLayout(this);box.setOrientation(0);box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(13),dp(10),dp(13),dp(10));box.setBackground(shape(0xff27245e,0xff171a43,17));TextView label=text("♫  Ses",13,true);box.addView(label);SeekBar seek=new SeekBar(this);seek.setMax(audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC));seek.setProgress(audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));box.addView(seek,new LinearLayout.LayoutParams(0,dp(40),1));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean fromUser){if(fromUser)audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,p,0);}});TextView mute=text("  ◉ Sessiz",12,true);mute.setFocusable(true);mute.setOnClickListener(v->{audio.adjustStreamVolume(android.media.AudioManager.STREAM_MUSIC,android.media.AudioManager.ADJUST_TOGGLE_MUTE,0);seek.setProgress(audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));});box.addView(mute);content.addView(box);}
